Plugins.Require("item_skill", "client.listener.Listener")
-- Plugins.Require("item_skill", "client.entity.ClientMonster")
Plugins.Require("item_skill", "client.packet.PacketHandler")
Plugins.Require("item_skill", "client.manager.SkillManager")

local handlers = {}

function handlers.updateSkillParam(blockPos)
    local lua_player = PlayerManager:getClientPlayer()
    local holdId = lua_player:getHeldItemId()
    local skill = SkillConfig:getSkill(holdId)
    if skill and skill.isPlaceBlock then
        lua_player:sendPacket({
            pid = "UpdateSkillParam",
            blockPos = blockPos
        })
        local useResult = Blockman.Instance().m_playerControl:useItem(lua_player.Player, EngineWorld:getWorld(), lua_player.Player:getHeldItem())
    end
end


return handlers